"""Campaign compiler, typed replay, filtering and state preparation.

The pipeline turns one recorded campaign into its certificate: a plan per
entry, one record per recorded witness and the corpus of distinct inputs.
"""

from .ast import Module, TypeEnv
from .composer import DependencyGraph
from .expr import compile_predicate
from .oracles import DeclarationCollector, LayoutBuilder, LeafError, recover
from .run import Corpus, corpus_key
from .state import Machine, Preparer, group_guards
from . import wire


class EntryPlan(object):
    """Everything the certificate and the runner need about one entry."""

    __slots__ = ('name', 'module', 'order', 'declarations', 'slots', 'flag',
                 'flag_id', 'variables', 'expected', 'roots', 'result')

    def __init__(self, name):
        self.name = name
        self.module = None
        self.order = []
        self.declarations = []
        self.slots = []
        self.flag = None
        self.flag_id = None
        self.variables = 0
        self.expected = {}
        self.roots = []
        self.result = None

    def certificate(self):
        return {
            'entry': self.name,
            'modules': list(self.order),
            'types': list(self.declarations),
            'slots': [list(slot) for slot in self.slots],
            'flag': self.flag,
            'variables': self.variables,
        }


def _pipes_by_target(pipes):
    grouped = {}
    for target, filter_module, bind in pipes:
        grouped.setdefault(target, []).append((target, filter_module, bind))
    return grouped


def _module_accepts(name, values, modules, grouped):
    """True when a module and every filter bound to it accept."""
    module = modules[name]
    if module.requires is not None and not module.requires(values):
        return False
    for _target, filter_module, bind in grouped.get(name, ()):
        bound = {}
        for filter_param, target_param in bind.items():
            bound[filter_param] = values[target_param]
        if not _module_accepts(filter_module, bound, modules, grouped):
            return False
    return True


def _filters_accept(entry, values, modules, grouped):
    """True when every filter bound to the entry accepts."""
    for _target, filter_module, bind in grouped.get(entry, ()):
        bound = {}
        for filter_param, target_param in bind.items():
            bound[filter_param] = values[target_param]
        if not _module_accepts(filter_module, bound, modules, grouped):
            return False
    return True


def _build_plan(name, modules, graph, types, grouped):
    plan = EntryPlan(name)
    module = modules[name]
    plan.module = module
    plan.order = graph.compile_order(name)
    collector = DeclarationCollector()
    for module_name in plan.order:
        other = modules[module_name]
        for _param_name, param_type in other.params:
            collector.collect(param_type)
        collector.collect(other.result[1])
    plan.declarations = collector.result()

    builder = LayoutBuilder()
    for param_name, param_type in module.params:
        plan.roots.append(builder.build(param_type, [param_name]))
    if module.result_type().kind != 'void':
        plan.result = builder.build(module.result[1], [module.result[0]])
    if grouped.get(name):
        plan.flag_id = builder.count
        plan.flag = 'x%d' % builder.count
        builder.count += 1
    plan.slots = builder.slots
    plan.variables = builder.count
    expected = {}
    for slot_name, _path, width in builder.slots:
        expected[slot_name] = width
    if plan.flag is not None:
        expected[plan.flag] = 1
    plan.expected = expected
    return plan


def execute(campaign):
    """Compile a campaign into its certificate."""
    if not isinstance(campaign, dict):
        raise ValueError('campaign must be an object')
    types = TypeEnv(campaign.get('types') or [])
    modules = {}
    for spec in campaign.get('modules') or ():
        params = [(item[0], types.get(item[1])) for item in spec['params']]
        result = (spec['result'][0], types.get(spec['result'][1]))
        module = Module(spec['name'], params, result, None, spec.get('requires'))
        modules[module.name] = module
    for module in modules.values():
        module.requires = compile_predicate(module.raw_requires,
                                            module.scope(), types)

    graph = DependencyGraph()
    for edge in campaign.get('calls') or ():
        graph.add_call(edge[0], edge[1])
    pipes = []
    for spec in campaign.get('pipes') or ():
        target = spec['target']
        filter_module = spec['filter']
        bind = dict(spec['bind'])
        graph.add_pipe(target, filter_module)
        pipes.append((target, filter_module, bind))
    grouped = _pipes_by_target(pipes)

    entries = list(campaign.get('entries') or ())
    runs = list(campaign.get('runs') or ())
    machine_spec = campaign.get('machine')
    machine = Machine(machine_spec) if machine_spec else None

    plans = {}
    plan_order = []
    for entry in entries:
        plan = _build_plan(entry, modules, graph, types, grouped)
        plans[entry] = plan
        plan_order.append(plan)

    preparers = {}
    if machine is not None:
        for entry in entries:
            module = modules[entry]
            scope = module.scope()
            guards = [transition.get('when')
                      for transition in machine.transitions]
            group_of, groups = group_guards(guards)
            functions = [compile_predicate(guard, scope, types)
                         for guard in groups]
            preparers[entry] = Preparer(machine, group_of, functions)

    corpus = Corpus()
    records = []
    for index, run in enumerate(runs):
        try:
            record = _run(index, run, plans, modules, grouped, machine,
                          preparers, corpus, types)
        except Exception:
            record = {'status': 'INVALID_TEST'}
        records.append(record)
    return {
        'plans': [plan.certificate() for plan in plan_order],
        'records': records,
        'corpus': corpus.result(),
    }


def _run(index, run, plans, modules, grouped, machine, preparers, corpus,
         types):
    """Evaluate one recorded witness."""
    entry = run['entry']
    plan = plans[entry]
    try:
        objects = wire.decode(run['ktest'])
        wire.check_inventory(objects, plan.expected)
        values = wire.values(objects)
    except wire.InvalidTest:
        return {'status': 'INVALID_TEST'}
    try:
        recovered = {}
        for (param_name, _param_type), node in zip(plan.module.params,
                                                   plan.roots):
            recovered[param_name] = recover(node, values)
        model_result = None
        if plan.result is not None:
            model_result = recover(plan.result, values)
    except LeafError:
        return {'status': 'INVALID_TEST'}

    accepted = _filters_accept(entry, recovered, modules, grouped)
    if plan.flag is not None:
        expected_flag = 0 if accepted else 1
        if values[plan.flag_id] != expected_flag:
            return {'status': 'INVALID_TEST'}

    module = plan.module
    if module.requires is not None and not module.requires(recovered):
        return {'status': 'FILTERED'}
    if not accepted:
        return {'status': 'FILTERED'}

    if machine is None:
        commands = []
        cost = 0
    else:
        preparer = preparers[entry]
        desired = recovered[machine.state_param]
        message = recovered[machine.message_param]
        signature = preparer.signature(recovered)
        preparation = preparer.prepare(desired, signature)
        if preparation is None:
            return {'status': 'UNREACHABLE'}
        commands = list(preparation[0]) + [message]
        cost = preparation[1]

    key = corpus_key(entry, plan.module.params, recovered)
    position = corpus.lookup(key)
    if position is None:
        inputs = {}
        for param_name, _param_type in plan.module.params:
            inputs[param_name] = recovered[param_name]
        position = corpus.add(key, entry, inputs, cost, commands, index)
        return {'status': 'READY', 'case': position,
                'model_result': model_result}
    corpus.witness(position, index)
    return {'status': 'DUPLICATE', 'case': position,
            'model_result': model_result}
